// Motion in a Straight Line (Physics) - Question Bank
// Format follows the same schema used across the practice app:
// { id, type, question, options, correctIndex, explanation, difficulty }
// type: 'mcq' | 'assertion' | 'matching' | 'statement' | 'count'
// Note: theory-focused, with only simple/light numerical questions included, per request.

export const MOTION_STRAIGHT_LINE = [

  // ============ FRAME OF REFERENCE, REST AND MOTION ============
  { id: 'msl-1', type: 'mcq', question: 'A body is said to be in motion if its position changes with:', options: ['Time, relative to a chosen reference point', 'Mass, regardless of time', 'Temperature, regardless of position', 'Colour, regardless of any other factor'], correctIndex: 0, explanation: 'Motion is defined as a change in the position of an object with time, with respect to a chosen reference point (frame of reference).', difficulty: 'easy' },
  { id: 'msl-2', type: 'mcq', question: 'The coordinate system, along with a clock, used to specify the position and describe the motion of an object is called a:', options: ['Frame of reference', 'Point object', 'Trajectory', 'Path length'], correctIndex: 0, explanation: 'A frame of reference consists of a coordinate system and a clock, allowing the position of an object to be specified at different times.', difficulty: 'easy' },
  { id: 'msl-3', type: 'mcq', question: 'The most commonly used frame of reference, in which the axes are mutually perpendicular, is called a:', options: ['Cartesian coordinate system', 'Polar coordinate system exclusively', 'Non-inertial system only', 'Curved coordinate system'], correctIndex: 0, explanation: 'A Cartesian coordinate system, with mutually perpendicular axes, is the most commonly used frame of reference in describing motion.', difficulty: 'medium' },
  { id: 'msl-4', type: 'mcq', question: 'Both rest and motion are considered relative concepts because:', options: ['An object can be at rest with respect to one frame of reference, but in motion with respect to another', 'An object is always at rest, regardless of the observer\'s frame of reference', 'An object is always in motion, regardless of any frame of reference', 'Rest and motion have no dependence on the choice of frame of reference'], correctIndex: 0, explanation: 'Whether an object is described as being at rest or in motion depends on the frame of reference chosen; the same object can be at rest relative to one frame and in motion relative to another.', difficulty: 'medium' },
  { id: 'msl-5', type: 'mcq', question: 'When the size of a body is negligible in comparison to the distance it moves in a reasonable amount of time, the body can be treated, for the purposes of motion analysis, as a:', options: ['Point object', 'Rigid body of infinite extent', 'Non-physical entity', 'Two-dimensional plane'], correctIndex: 0, explanation: 'A body is treated as a point object when its size is negligible compared to the distances involved in its motion, simplifying the analysis.', difficulty: 'medium' },
  { id: 'msl-6', type: 'assertion', question: 'Assertion (A): A passenger sitting inside a moving train can be considered both at rest and in motion simultaneously.\nReason (R): The passenger is at rest with respect to the train (frame of reference: train) but in motion with respect to the ground (frame of reference: earth).', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The dependence of motion description on the chosen frame of reference correctly explains how the same passenger can be simultaneously "at rest" and "in motion" relative to different frames.', difficulty: 'medium' },
  { id: 'msl-7', type: 'count', question: 'Consider the following statements about frame of reference and motion:\n1. Motion is defined as a change in position with time.\n2. A frame of reference consists only of a coordinate system, without any timing mechanism.\n3. Whether a body is at rest or in motion depends on the observer\'s frame of reference.\n4. A point object approximation is valid when the object\'s size is negligible relative to the distances involved in its motion.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — a frame of reference includes both a coordinate system and a clock (timing mechanism).', difficulty: 'medium' },

  // ============ DISTANCE AND DISPLACEMENT ============
  { id: 'msl-8', type: 'mcq', question: 'The total length of the actual path travelled by an object, irrespective of direction, is called its:', options: ['Distance', 'Displacement', 'Velocity', 'Acceleration'], correctIndex: 0, explanation: 'Distance refers to the total path length covered by an object during its motion, regardless of the direction of travel.', difficulty: 'easy' },
  { id: 'msl-9', type: 'mcq', question: 'The shortest, straight-line distance between the initial and final position of an object, along with a specified direction, is called its:', options: ['Distance', 'Displacement', 'Speed', 'Path length'], correctIndex: 1, explanation: 'Displacement is the change in position, i.e., the straight-line vector from the initial to the final position, having both magnitude and direction.', difficulty: 'easy' },
  { id: 'msl-10', type: 'mcq', question: 'Distance is a scalar quantity, whereas displacement is a:', options: ['Vector quantity', 'Also a scalar quantity, exactly like distance', 'Dimensionless quantity', 'Tensor quantity, not a simple vector'], correctIndex: 0, explanation: 'Distance is a scalar (magnitude only), while displacement is a vector quantity, possessing both magnitude and direction.', difficulty: 'easy' },
  { id: 'msl-11', type: 'mcq', question: 'For any given motion of an object, the magnitude of the displacement is:', options: ['Always greater than the distance travelled', 'Always less than or equal to the distance travelled', 'Always exactly equal to the distance travelled, in every case', 'Unrelated to the distance travelled'], correctIndex: 1, explanation: 'The magnitude of displacement can never exceed the total distance travelled; they are equal only when the motion occurs along a straight line without any reversal in direction.', difficulty: 'medium' },
  { id: 'msl-12', type: 'mcq', question: 'If an object moves along a straight path in one direction without reversing, then the magnitude of its displacement is:', options: ['Equal to the distance travelled', 'Always less than the distance travelled', 'Always greater than the distance travelled', 'Undefined, since displacement cannot be calculated for straight-line motion'], correctIndex: 0, explanation: 'When motion occurs in a single direction along a straight line without any reversal, the magnitude of displacement equals the distance travelled.', difficulty: 'medium' },
  { id: 'msl-13', type: 'mcq', question: 'If an object returns to its exact starting point after some motion, its net displacement for the entire trip is:', options: ['Zero, even though the distance travelled may be non-zero', 'Always equal to the total distance travelled', 'Undefined in every such case', 'Always negative'], correctIndex: 0, explanation: 'When an object returns to its starting point, its net displacement is zero, even though the total distance travelled during the trip is generally non-zero.', difficulty: 'medium' },
  { id: 'msl-14', type: 'assertion', question: 'Assertion (A): The distance travelled by an object can never be less than the magnitude of its displacement.\nReason (R): Displacement represents the shortest, straight-line path between two points, while distance accounts for the entire actual path taken, which can be equal to or longer than this straight-line path.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Since the actual path is always at least as long as the straight-line shortest path, the assertion is correctly explained by the definitions given in R.', difficulty: 'medium' },
  { id: 'msl-15', type: 'count', question: 'Consider the following statements about distance and displacement:\n1. Distance is a scalar quantity.\n2. Displacement is a vector quantity.\n3. The magnitude of displacement can sometimes exceed the total distance travelled.\n4. If an object returns to its starting point, its displacement is zero.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — the magnitude of displacement can never exceed the total distance travelled.', difficulty: 'medium' },
  { id: 'msl-16', type: 'matching', question: 'Match Column I (quantity) with Column II (nature):\nColumn I: A. Distance  B. Displacement  C. Speed  D. Velocity\nColumn II: i. Vector  ii. Scalar  iii. Vector  iv. Scalar', options: ['A-ii, B-i, C-iv, D-iii', 'A-i, B-ii, C-iii, D-iv', 'A-ii, B-iv, C-i, D-iii', 'A-iv, B-i, C-ii, D-iii'], correctIndex: 0, explanation: 'Distance — scalar; Displacement — vector; Speed — scalar; Velocity — vector.', difficulty: 'easy' },

  // ============ UNIFORM AND NON-UNIFORM MOTION ============
  { id: 'msl-17', type: 'mcq', question: 'When an object covers equal distances in equal intervals of time, regardless of how small these time intervals are, the motion is described as:', options: ['Uniform motion', 'Non-uniform motion', 'Accelerated motion, exclusively', 'Random motion'], correctIndex: 0, explanation: 'Uniform motion is characterised by an object covering equal distances in equal intervals of time.', difficulty: 'easy' },
  { id: 'msl-18', type: 'mcq', question: 'When an object covers unequal distances in equal intervals of time, the motion is described as:', options: ['Uniform motion', 'Non-uniform motion', 'Circular motion, exclusively', 'Reference-frame independent motion'], correctIndex: 1, explanation: 'Non-uniform motion occurs when an object covers unequal distances in equal time intervals, generally implying a change in speed or direction.', difficulty: 'easy' },
  { id: 'msl-19', type: 'assertion', question: 'Assertion (A): An object undergoing uniform motion has zero acceleration.\nReason (R): Since uniform motion implies a constant speed and unchanging direction (along a straight line), the velocity of the object remains constant, and therefore its rate of change of velocity (acceleration) is zero.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Since velocity remains unchanged during uniform motion along a straight line, acceleration is necessarily zero, correctly explaining the assertion.', difficulty: 'medium' },

  // ============ SPEED (AVERAGE AND INSTANTANEOUS) ============
  { id: 'msl-20', type: 'mcq', question: 'The total distance travelled by an object divided by the total time taken is called its:', options: ['Average speed', 'Instantaneous speed', 'Average velocity, exclusively', 'Instantaneous velocity'], correctIndex: 0, explanation: 'Average speed is defined as the total distance travelled divided by the total time taken for the journey.', difficulty: 'easy' },
  { id: 'msl-21', type: 'mcq', question: 'The speed of an object at a particular (specific) instant of time is called its:', options: ['Average speed', 'Instantaneous speed', 'Uniform speed, only', 'Relative speed, exclusively'], correctIndex: 1, explanation: 'Instantaneous speed refers to the speed of an object at a specific moment in time, essentially the limiting value of average speed as the time interval approaches zero.', difficulty: 'medium' },
  { id: 'msl-22', type: 'mcq', question: 'Speed, as a physical quantity, is classified as a:', options: ['Scalar quantity', 'Vector quantity', 'Dimensionless quantity', 'Tensor quantity'], correctIndex: 0, explanation: 'Speed is a scalar quantity, defined only by its magnitude (how fast an object is moving), without reference to direction.', difficulty: 'easy' },
  { id: 'msl-23', type: 'mcq', question: 'The average speed of an object over a given time interval is always:', options: ['Greater than or equal to the magnitude of its average velocity over the same interval', 'Always exactly equal to the magnitude of its average velocity', 'Always less than the magnitude of its average velocity', 'Unrelated to the average velocity in any way'], correctIndex: 0, explanation: 'Since average speed uses total distance (which is ≥ the magnitude of displacement), average speed is always greater than or equal to the magnitude of average velocity.', difficulty: 'hard' },
  { id: 'msl-24', type: 'assertion', question: 'Assertion (A): It is possible for the average speed of a moving body to be non-zero while its average velocity over the same time interval is zero.\nReason (R): If a body returns to its exact starting point after moving along some path, its net displacement (and thus average velocity) is zero, even though it has covered a non-zero distance, giving a non-zero average speed.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The distinction between distance-based average speed and displacement-based average velocity, illustrated by a round trip, correctly explains this apparent discrepancy.', difficulty: 'medium' },
  { id: 'msl-25', type: 'count', question: 'Consider the following statements about speed:\n1. Speed is a vector quantity.\n2. Average speed is calculated as total distance divided by total time.\n3. Instantaneous speed refers to speed at a specific moment in time.\n4. Average speed can never be less than the magnitude of average velocity over the same time interval.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 2, 3 and 4 are correct. Statement 1 is wrong — speed is a scalar quantity, not a vector.', difficulty: 'medium' },

  // ============ VELOCITY (AVERAGE AND INSTANTANEOUS) ============
  { id: 'msl-26', type: 'mcq', question: 'The displacement of an object divided by the time interval during which the displacement occurs is called its:', options: ['Average velocity', 'Instantaneous speed', 'Average speed, exclusively', 'Acceleration'], correctIndex: 0, explanation: 'Average velocity is defined as the displacement divided by the time interval over which that displacement occurred.', difficulty: 'easy' },
  { id: 'msl-27', type: 'mcq', question: 'The velocity of an object at a specific instant of time, essentially the limiting value of average velocity as the time interval tends to zero, is called its:', options: ['Average velocity', 'Instantaneous velocity', 'Average speed', 'Relative displacement'], correctIndex: 1, explanation: 'Instantaneous velocity is the velocity of an object at a particular instant, obtained as the limit of average velocity as the time interval approaches zero.', difficulty: 'medium' },
  { id: 'msl-28', type: 'mcq', question: 'Velocity, unlike speed, is a physical quantity that has:', options: ['Both magnitude and direction', 'Only magnitude, without any direction', 'Neither magnitude nor direction', 'Only direction, without any defined magnitude'], correctIndex: 0, explanation: 'Velocity is a vector quantity, possessing both magnitude (speed in a given direction) and direction.', difficulty: 'easy' },
  { id: 'msl-29', type: 'mcq', question: 'If an object moves with a constant (uniform) velocity, its average velocity over any time interval during the motion:', options: ['Equals its instantaneous velocity at any point during that interval', 'Is always different from its instantaneous velocity', 'Cannot be determined at all', 'Is always zero, by definition'], correctIndex: 0, explanation: 'For motion at constant velocity, the average velocity over any interval equals the (unchanging) instantaneous velocity throughout that interval.', difficulty: 'medium' },
  { id: 'msl-30', type: 'assertion', question: 'Assertion (A): The magnitude of the instantaneous velocity of an object is equal to its instantaneous speed.\nReason (R): As the time interval used to compute average velocity shrinks to an infinitesimally small value, the path travelled and the displacement effectively coincide, so the magnitude of instantaneous velocity equals instantaneous speed.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The convergence of path length and displacement magnitude in the infinitesimal time limit correctly explains why instantaneous speed equals the magnitude of instantaneous velocity.', difficulty: 'hard' },
  { id: 'msl-31', type: 'count', question: 'Consider the following statements about velocity:\n1. Velocity is a vector quantity.\n2. Average velocity is calculated as displacement divided by time interval.\n3. Instantaneous velocity is always less than average velocity, in every case.\n4. For uniform (constant) velocity motion, average and instantaneous velocities are equal.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — there is no general rule that instantaneous velocity is always less than average velocity; this depends on the specific motion.', difficulty: 'medium' },

  // ============ ACCELERATION ============
  { id: 'msl-32', type: 'mcq', question: 'The rate of change of velocity of an object with time is called its:', options: ['Speed', 'Acceleration', 'Displacement', 'Distance'], correctIndex: 1, explanation: 'Acceleration is defined as the rate of change of velocity with respect to time.', difficulty: 'easy' },
  { id: 'msl-33', type: 'mcq', question: 'Acceleration, like velocity, is classified as a:', options: ['Vector quantity', 'Scalar quantity', 'Dimensionless quantity', 'Tensor quantity, unlike velocity'], correctIndex: 0, explanation: 'Acceleration is a vector quantity, having both magnitude and direction, just like velocity and displacement.', difficulty: 'easy' },
  { id: 'msl-34', type: 'mcq', question: 'The change in velocity of an object over a given time interval, divided by that time interval, is called its:', options: ['Average acceleration', 'Instantaneous acceleration', 'Average speed', 'Average displacement'], correctIndex: 0, explanation: 'Average acceleration is the change in velocity divided by the corresponding time interval.', difficulty: 'medium' },
  { id: 'msl-35', type: 'mcq', question: 'The acceleration of an object at a specific instant of time, obtained as the limiting value of average acceleration as the time interval tends to zero, is called its:', options: ['Average acceleration', 'Instantaneous acceleration', 'Uniform acceleration exclusively', 'Relative acceleration exclusively'], correctIndex: 1, explanation: 'Instantaneous acceleration is the acceleration of an object at a particular moment, defined as the limit of average acceleration as the time interval approaches zero.', difficulty: 'medium' },
  { id: 'msl-36', type: 'mcq', question: 'When the velocity of an object changes by equal amounts in equal intervals of time, the acceleration is described as:', options: ['Uniform acceleration', 'Non-uniform acceleration', 'Zero acceleration', 'Undefined acceleration'], correctIndex: 0, explanation: 'Uniform acceleration occurs when the velocity of an object changes by equal amounts in equal time intervals.', difficulty: 'medium' },
  { id: 'msl-37', type: 'mcq', question: 'When the velocity of an object changes by unequal amounts in equal intervals of time, the acceleration is described as:', options: ['Uniform acceleration', 'Non-uniform acceleration', 'Constant acceleration', 'Zero acceleration'], correctIndex: 1, explanation: 'Non-uniform acceleration occurs when velocity changes by unequal amounts over equal time intervals.', difficulty: 'medium' },
  { id: 'msl-38', type: 'mcq', question: 'When the velocity of a moving object increases with time, its acceleration is generally in the:', options: ['Same direction as the velocity', 'Opposite direction to the velocity', 'Always perpendicular to the velocity', 'It cannot be determined without additional information, in every case'], correctIndex: 0, explanation: 'When speed increases in a given direction, the acceleration is generally in the same direction as the velocity (positive acceleration).', difficulty: 'medium' },
  { id: 'msl-39', type: 'mcq', question: 'When the velocity of a moving object decreases with time, its acceleration acts in a direction:', options: ['Opposite to the direction of velocity (often called deceleration or retardation)', 'The same as the direction of velocity, always', 'Perpendicular to the direction of velocity, in all one-dimensional motion', 'Undefined, since deceleration has no acceleration associated with it'], correctIndex: 0, explanation: 'When an object slows down, its acceleration is directed opposite to its velocity, a situation often referred to as deceleration or retardation.', difficulty: 'medium' },
  { id: 'msl-40', type: 'assertion', question: 'Assertion (A): An object can have zero velocity at a given instant while simultaneously having a non-zero acceleration.\nReason (R): At the highest point of a vertically thrown object\'s trajectory, its instantaneous velocity is momentarily zero, but the acceleration due to gravity continues to act on it throughout its motion.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The classic example of a vertically thrown object at its highest point correctly illustrates and explains how zero instantaneous velocity can coexist with non-zero acceleration.', difficulty: 'medium' },
  { id: 'msl-41', type: 'assertion', question: 'Assertion (A): If the velocity of an object is zero at a given instant, its acceleration at that instant must also be zero.\nReason (R): Acceleration is directly proportional to velocity at every instant, so any object with zero velocity must necessarily have zero acceleration as well.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 3, explanation: 'The assertion is false — an object can have zero velocity with non-zero acceleration (e.g., at the peak of vertical projectile motion). The reason given (that acceleration is directly proportional to velocity) is also false, since acceleration depends on the rate of change of velocity, not velocity itself.', difficulty: 'hard' },
  { id: 'msl-42', type: 'count', question: 'Consider the following statements about acceleration:\n1. Acceleration is a scalar quantity.\n2. Uniform acceleration means the velocity changes by equal amounts in equal time intervals.\n3. An object can have zero velocity and non-zero acceleration simultaneously.\n4. Deceleration refers to acceleration acting in the same direction as velocity.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 2 and 3 are correct. Statement 1 is wrong (acceleration is a vector, not scalar), and statement 4 is wrong (deceleration means acceleration acts opposite to velocity, not in the same direction).', difficulty: 'medium' },

  // ============ POSITION-TIME GRAPHS ============
  { id: 'msl-43', type: 'mcq', question: 'On a position-time graph, the slope of the graph at any point represents the:', options: ['Velocity of the object at that point', 'Acceleration of the object at that point', 'Displacement of the object at that point', 'Distance travelled up to that point'], correctIndex: 0, explanation: 'The slope of a position-time graph at any instant gives the instantaneous velocity of the object at that instant.', difficulty: 'medium' },
  { id: 'msl-44', type: 'mcq', question: 'A straight, horizontal line on a position-time graph indicates that the object is:', options: ['At rest (stationary), with a fixed position over time', 'Moving with a constant, non-zero velocity', 'Accelerating uniformly', 'Undergoing non-uniform motion'], correctIndex: 0, explanation: 'A horizontal line on a position-time graph, with zero slope, indicates that the object\'s position is not changing, meaning it is at rest.', difficulty: 'medium' },
  { id: 'msl-45', type: 'mcq', question: 'A straight, inclined line (with constant, non-zero slope) on a position-time graph indicates that the object is undergoing:', options: ['Uniform motion, i.e., moving with constant velocity', 'Non-uniform (accelerated) motion', 'No motion at all', 'Circular motion'], correctIndex: 0, explanation: 'A straight inclined line, having a constant slope, indicates that the object is moving with a constant velocity, i.e., uniform motion.', difficulty: 'medium' },
  { id: 'msl-46', type: 'mcq', question: 'A curved line on a position-time graph, where the slope changes continuously, indicates that the object is undergoing:', options: ['Non-uniform (accelerated) motion', 'Uniform motion with constant velocity', 'A state of rest', 'Motion with zero acceleration throughout'], correctIndex: 0, explanation: 'A curved position-time graph, with continuously changing slope, indicates that the object\'s velocity is changing, i.e., it is undergoing accelerated (non-uniform) motion.', difficulty: 'medium' },
  { id: 'msl-47', type: 'assertion', question: 'Assertion (A): The slope of a position-time graph becoming steeper over time indicates that the object is accelerating.\nReason (R): A steeper slope on a position-time graph corresponds to a larger velocity, and if the slope continuously increases with time, the velocity is increasing, indicating positive acceleration.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The relationship between slope steepness and increasing velocity correctly explains why an increasingly steep position-time graph indicates acceleration.', difficulty: 'medium' },
  { id: 'msl-48', type: 'count', question: 'Consider the following statements about position-time graphs:\n1. The slope at any point gives the instantaneous velocity.\n2. A horizontal line indicates the object is moving with maximum velocity.\n3. A straight, inclined line with constant slope indicates uniform velocity.\n4. A curved graph indicates that the object\'s velocity is changing over time.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — a horizontal line indicates the object is at rest (zero velocity), not moving at maximum velocity.', difficulty: 'medium' },

  // ============ VELOCITY-TIME GRAPHS ============
  { id: 'msl-49', type: 'mcq', question: 'On a velocity-time graph, the slope of the graph at any point represents the:', options: ['Acceleration of the object at that point', 'Displacement of the object at that point', 'Distance travelled up to that point', 'Position of the object at that point'], correctIndex: 0, explanation: 'The slope of a velocity-time graph at any instant gives the instantaneous acceleration of the object.', difficulty: 'medium' },
  { id: 'msl-50', type: 'mcq', question: 'On a velocity-time graph, the area enclosed between the graph line and the time axis, over a given time interval, represents the:', options: ['Displacement of the object during that time interval', 'Acceleration of the object during that time interval', 'The average velocity, but never the displacement', 'Nothing physically meaningful'], correctIndex: 0, explanation: 'The area under a velocity-time graph, between the curve and the time axis, gives the displacement of the object during that interval.', difficulty: 'medium' },
  { id: 'msl-51', type: 'mcq', question: 'A straight, horizontal line on a velocity-time graph, above the time axis, indicates that the object is moving with:', options: ['A constant, non-zero velocity', 'Zero velocity throughout', 'A constantly increasing velocity', 'A constantly decreasing velocity'], correctIndex: 0, explanation: 'A horizontal line on a velocity-time graph (above the axis) indicates a constant, non-zero velocity, and hence zero acceleration.', difficulty: 'medium' },
  { id: 'msl-52', type: 'mcq', question: 'A straight, inclined line on a velocity-time graph, with constant positive slope, indicates that the object is undergoing:', options: ['Uniform (constant) positive acceleration', 'Uniform (constant) negative acceleration', 'Zero acceleration', 'Non-uniform acceleration'], correctIndex: 0, explanation: 'A straight line with a constant positive slope on a velocity-time graph indicates uniform (constant) positive acceleration.', difficulty: 'medium' },
  { id: 'msl-53', type: 'mcq', question: 'On a velocity-time graph, a region where the velocity value is below the time axis (negative) indicates that the object is:', options: ['Moving in the direction opposite to the chosen positive direction', 'Not moving at all', 'Undergoing infinite acceleration', 'Moving faster than at any other point on the graph, regardless of sign'], correctIndex: 0, explanation: 'A negative value on the velocity axis simply indicates motion in the direction opposite to the chosen positive reference direction.', difficulty: 'medium' },
  { id: 'msl-54', type: 'assertion', question: 'Assertion (A): The area under a velocity-time graph can be used to calculate the displacement of an object, even if its acceleration is non-uniform.\nReason (R): The area under any velocity-time graph, regardless of the shape of the curve, mathematically represents the total displacement, since displacement is the integral of velocity with respect to time.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The mathematical relationship between displacement and the integral of velocity over time correctly explains why the area under any velocity-time graph gives displacement, regardless of whether acceleration is uniform.', difficulty: 'hard' },
  { id: 'msl-55', type: 'count', question: 'Consider the following statements about velocity-time graphs:\n1. The slope of a velocity-time graph gives acceleration.\n2. The area under a velocity-time graph gives displacement.\n3. A horizontal line on a velocity-time graph indicates constant acceleration.\n4. A straight, inclined line on a velocity-time graph indicates uniform acceleration.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — a horizontal line on a velocity-time graph indicates constant velocity (and hence zero acceleration), not constant non-zero acceleration.', difficulty: 'medium' },
  { id: 'msl-56', type: 'matching', question: 'Match Column I (graph type) with Column II (what the slope represents):\nColumn I: A. Position-time graph  B. Velocity-time graph\nColumn II: i. Acceleration  ii. Velocity', options: ['A-ii, B-i', 'A-i, B-ii', 'Both give acceleration', 'Both give velocity'], correctIndex: 0, explanation: 'Position-time graph slope — velocity; Velocity-time graph slope — acceleration.', difficulty: 'medium' },

  // ============ EQUATIONS OF MOTION FOR UNIFORM ACCELERATION ============
  { id: 'msl-57', type: 'mcq', question: 'For an object undergoing uniformly accelerated motion in a straight line, the relationship between final velocity (v), initial velocity (u), acceleration (a), and time (t) is given by which of the following standard equations of motion?', options: ['v = u + at', 'v = u - at, always', 'v = u × at', 'v = u / at'], correctIndex: 0, explanation: 'The first equation of motion for uniformly accelerated motion is v = u + at, relating final velocity, initial velocity, acceleration and time.', difficulty: 'easy' },
  { id: 'msl-58', type: 'mcq', question: 'For an object undergoing uniformly accelerated motion, the displacement (s) in terms of initial velocity (u), time (t), and acceleration (a) is given by:', options: ['s = ut + (1/2)at²', 's = ut - (1/2)at², always', 's = u + at²', 's = u²t + at'], correctIndex: 0, explanation: 'The second equation of motion is s = ut + (1/2)at², giving the displacement in terms of initial velocity, time and acceleration.', difficulty: 'easy' },
  { id: 'msl-59', type: 'mcq', question: 'For an object undergoing uniformly accelerated motion, the relationship between final velocity (v), initial velocity (u), acceleration (a), and displacement (s), without reference to time, is given by:', options: ['v² = u² + 2as', 'v = u² + 2as', 'v² = u + 2as', 'v² = u² - 2as, always'], correctIndex: 0, explanation: 'The third equation of motion, v² = u² + 2as, relates final velocity, initial velocity, acceleration and displacement, without explicitly involving time.', difficulty: 'easy' },
  { id: 'msl-60', type: 'mcq', question: 'The standard equations of motion (v = u + at; s = ut + ½at²; v² = u² + 2as) are valid specifically for motion with:', options: ['Uniform (constant) acceleration', 'Any type of non-uniform, variable acceleration', 'Zero acceleration exclusively', 'Only circular motion'], correctIndex: 0, explanation: 'These standard kinematic equations apply specifically to motion under uniform (constant) acceleration; they do not directly apply to motion with variable (non-uniform) acceleration.', difficulty: 'medium' },
  { id: 'msl-61', type: 'mcq', question: 'In the equations of motion, the sign convention typically used dictates that quantities in the direction of the assumed positive direction are taken as positive, while quantities in the opposite direction are taken as:', options: ['Negative', 'Also positive, without exception', 'Zero, regardless of actual direction', 'Undefined'], correctIndex: 0, explanation: 'A consistent sign convention is used, where quantities (like displacement, velocity, acceleration) opposite to the chosen positive direction are assigned negative values.', difficulty: 'medium' },
  { id: 'msl-62', type: 'assertion', question: 'Assertion (A): The standard equations of motion cannot be directly used to solve problems involving non-uniform (variable) acceleration.\nReason (R): These equations are derived under the specific assumption that acceleration remains constant throughout the motion; if acceleration varies with time, the derivations (and hence the equations themselves) no longer hold.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Since the equations are derived assuming constant acceleration, their invalidity for variable acceleration is correctly explained by R.', difficulty: 'medium' },
  { id: 'msl-63', type: 'count', question: 'Consider the following statements about the equations of motion:\n1. v = u + at relates final velocity, initial velocity, acceleration and time.\n2. s = ut + (1/2)at² gives displacement in terms of initial velocity, time and acceleration.\n3. v² = u² + 2as is valid for motion with any type of variable acceleration.\n4. These equations require a consistent sign convention for displacement, velocity and acceleration.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — these equations are valid only for uniform (constant) acceleration, not variable acceleration.', difficulty: 'medium' },
  { id: 'msl-64', type: 'mcq', question: 'A car starts from rest and accelerates uniformly at 2 m/s² for 5 seconds. Using v = u + at, its final velocity is:', options: ['10 m/s', '2 m/s', '5 m/s', '20 m/s'], correctIndex: 0, explanation: 'v = u + at = 0 + (2 × 5) = 10 m/s.', difficulty: 'easy' },
  { id: 'msl-65', type: 'mcq', question: 'Using the same scenario (u = 0, a = 2 m/s², t = 5 s), the displacement of the car, using s = ut + (1/2)at², is:', options: ['25 m', '10 m', '50 m', '5 m'], correctIndex: 0, explanation: 's = ut + (1/2)at² = 0 + (1/2)(2)(5²) = (1/2)(2)(25) = 25 m.', difficulty: 'medium' },

  // ============ MOTION UNDER GRAVITY (FREE FALL) ============
  { id: 'msl-66', type: 'mcq', question: 'When an object falls freely under the influence of gravity alone, near the surface of the Earth, it experiences a constant acceleration called the:', options: ['Acceleration due to gravity', 'Centripetal acceleration', 'Angular acceleration', 'Tangential acceleration'], correctIndex: 0, explanation: 'A freely falling object near the Earth\'s surface experiences a constant downward acceleration known as the acceleration due to gravity (denoted g).', difficulty: 'easy' },
  { id: 'msl-67', type: 'mcq', question: 'The standard value of the acceleration due to gravity (g) near the surface of the Earth is approximately:', options: ['9.8 m/s²', '9.8 m/s', '98 m/s²', '0.98 m/s²'], correctIndex: 0, explanation: 'The acceleration due to gravity near the Earth\'s surface is approximately 9.8 m/s².', difficulty: 'easy' },
  { id: 'msl-68', type: 'mcq', question: 'For an object undergoing free fall (motion under gravity alone, neglecting air resistance), the standard equations of motion can be directly applied, treating acceleration due to gravity as:', options: ['A constant acceleration (g), acting vertically downward', 'A variable, unpredictable acceleration', 'Zero, since gravity does not affect motion', 'Only applicable in horizontal motion, never vertical'], correctIndex: 0, explanation: 'Since g is constant near the Earth\'s surface, motion under gravity (in the absence of air resistance) can be analysed using the same standard equations of motion applicable to any uniformly accelerated motion.', difficulty: 'medium' },
  { id: 'msl-69', type: 'mcq', question: 'When an object is thrown vertically upward, its velocity decreases as it rises because the acceleration due to gravity acts:', options: ['In the direction opposite to its initial upward velocity', 'In the same direction as its initial upward velocity', 'Only horizontally, with no vertical component', 'Only at the exact highest point, and nowhere else during the ascent'], correctIndex: 0, explanation: 'Gravity acts downward at all times, opposing the initial upward velocity of a vertically thrown object, causing it to decelerate as it rises.', difficulty: 'medium' },
  { id: 'msl-70', type: 'mcq', question: 'At the highest point of the trajectory of a vertically thrown object, its instantaneous velocity is:', options: ['Zero, momentarily', 'Maximum, exactly equal to the initial launch velocity', 'Undefined, since velocity cannot be calculated at that instant', 'Always negative at that specific instant'], correctIndex: 0, explanation: 'At the highest point of vertical projectile motion, the object\'s velocity is momentarily zero before it begins to fall back down.', difficulty: 'medium' },
  { id: 'msl-71', type: 'mcq', question: 'For a vertically thrown object, neglecting air resistance, the time taken to reach the highest point (from launch) is:', options: ['Equal to the time taken to fall back down to the original launch height', 'Always greater than the time taken to fall back down', 'Always less than the time taken to fall back down', 'Completely unrelated to the time taken to fall back down'], correctIndex: 0, explanation: 'In the absence of air resistance, the time of ascent equals the time of descent for a vertically projected object returning to its original launch height, due to the symmetry of motion under constant gravitational acceleration.', difficulty: 'medium' },
  { id: 'msl-72', type: 'assertion', question: 'Assertion (A): Two objects of different masses, dropped from the same height in a vacuum, will reach the ground at exactly the same time.\nReason (R): In the absence of air resistance, the acceleration due to gravity is independent of the mass of the falling object.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The mass-independence of gravitational acceleration (in the absence of air resistance) correctly explains why objects of different masses fall at the same rate under such conditions.', difficulty: 'medium' },
  { id: 'msl-73', type: 'assertion', question: 'Assertion (A): The velocity of an object at the highest point of its vertical trajectory is zero, but its acceleration at that instant is not zero.\nReason (R): The acceleration due to gravity continues to act on the object throughout its entire trajectory, including at the highest point, regardless of the object\'s instantaneous velocity.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The continuous action of gravitational acceleration, independent of instantaneous velocity, correctly explains why acceleration remains non-zero at the highest point despite zero velocity.', difficulty: 'medium' },
  { id: 'msl-74', type: 'count', question: 'Consider the following statements about motion under gravity:\n1. The acceleration due to gravity near Earth\'s surface is approximately 9.8 m/s².\n2. For a vertically thrown object, velocity is zero at the highest point of its trajectory.\n3. In the presence of air resistance, all objects fall at exactly the same rate, regardless of shape or mass.\n4. The standard equations of motion can be applied to free-fall motion, treating g as a constant acceleration.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — air resistance causes objects of different shapes/masses to fall at different rates; the mass-independence of fall rate holds strictly only in a vacuum.', difficulty: 'medium' },
  { id: 'msl-75', type: 'mcq', question: 'A ball is dropped from rest and falls freely under gravity (g ≈ 10 m/s² for simplicity) for 2 seconds. Using v = u + gt, its velocity after 2 seconds is approximately:', options: ['20 m/s', '10 m/s', '5 m/s', '2 m/s'], correctIndex: 0, explanation: 'v = u + gt = 0 + (10 × 2) = 20 m/s.', difficulty: 'easy' },

  // ============ RELATIVE VELOCITY ============
  { id: 'msl-76', type: 'mcq', question: 'The velocity of an object as observed from another moving (or stationary) object, rather than from a fixed ground frame, is called its:', options: ['Relative velocity', 'Absolute velocity, exclusively', 'Instantaneous speed', 'Average acceleration'], correctIndex: 0, explanation: 'Relative velocity refers to the velocity of one object as measured or observed from the frame of reference of another object.', difficulty: 'medium' },
  { id: 'msl-77', type: 'mcq', question: 'The relative velocity of object A with respect to object B is calculated as:', options: ['The velocity of A minus the velocity of B (vector subtraction)', 'The velocity of A plus the velocity of B', 'The velocity of B minus the velocity of A', 'The average of the velocities of A and B'], correctIndex: 0, explanation: 'Relative velocity of A with respect to B is given by the vector difference: velocity of A minus velocity of B.', difficulty: 'medium' },
  { id: 'msl-78', type: 'mcq', question: 'If two objects are moving in the same direction along a straight line, the magnitude of their relative velocity (with respect to each other) is generally found by taking the:', options: ['Difference of their individual velocities', 'Sum of their individual velocities', 'Product of their individual velocities', 'Average of their individual velocities'], correctIndex: 0, explanation: 'For objects moving in the same direction, the relative velocity magnitude is found by subtracting one velocity from the other.', difficulty: 'medium' },
  { id: 'msl-79', type: 'mcq', question: 'If two objects are moving in opposite directions along a straight line, the magnitude of their relative velocity (with respect to each other) is generally found by taking the:', options: ['Sum of the magnitudes of their individual velocities', 'Difference of the magnitudes of their individual velocities', 'The velocity of only the faster-moving object', 'Always zero, regardless of their speeds'], correctIndex: 0, explanation: 'When two objects move in opposite directions, their relative velocity magnitude is found by adding the magnitudes of their individual velocities.', difficulty: 'medium' },
  { id: 'msl-80', type: 'assertion', question: 'Assertion (A): Two trains moving in the same direction at the same speed appear to be at rest relative to each other.\nReason (R): The relative velocity between two objects moving with identical velocity vectors (same speed and direction) is zero, since their velocity difference is zero.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The zero velocity difference between two objects moving identically correctly explains why they appear stationary relative to one another.', difficulty: 'medium' },
  { id: 'msl-81', type: 'count', question: 'Consider the following statements about relative velocity:\n1. Relative velocity of A with respect to B equals the velocity of A minus the velocity of B.\n2. For objects moving in the same direction, relative velocity magnitude is generally found by subtraction.\n3. For objects moving in opposite directions, relative velocity magnitude is generally found by addition.\n4. Relative velocity is a scalar quantity, unrelated to direction.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — relative velocity, like velocity itself, is a vector quantity, dependent on direction.', difficulty: 'medium' },

  // ============ STOPPING DISTANCE AND REACTION TIME ============
  { id: 'msl-82', type: 'mcq', question: 'When brakes are applied to a moving vehicle, the vehicle decelerates and eventually comes to rest; the distance travelled by the vehicle during this deceleration phase is called the:', options: ['Stopping distance', 'Reaction distance, exclusively', 'Braking coefficient', 'Terminal velocity distance'], correctIndex: 0, explanation: 'Stopping distance refers to the distance a vehicle travels from the moment the brakes are applied until it comes to a complete stop.', difficulty: 'medium' },
  { id: 'msl-83', type: 'mcq', question: 'For a given initial speed, the stopping distance of a vehicle is generally related to the magnitude of its deceleration (retardation) in what manner?', options: ['Stopping distance increases as deceleration decreases (weaker braking leads to a longer stopping distance)', 'Stopping distance is completely independent of the deceleration value', 'Stopping distance decreases as deceleration decreases', 'Stopping distance is always fixed, regardless of braking strength'], correctIndex: 0, explanation: 'For a given initial speed, weaker deceleration (braking) results in a longer stopping distance, and stronger deceleration results in a shorter one.', difficulty: 'medium' },
  { id: 'msl-84', type: 'mcq', question: 'The time interval between the perception of a need to act (such as noticing a hazard) and the actual initiation of the corresponding physical response (such as pressing the brake pedal) is called:', options: ['Reaction time', 'Stopping time, exclusively', 'Deceleration period', 'Terminal time'], correctIndex: 0, explanation: 'Reaction time is the delay between perceiving a stimulus (a need to act) and physically initiating the required response.', difficulty: 'medium' },
  { id: 'msl-85', type: 'mcq', question: 'During the reaction time of a driver (before brakes are physically applied), a moving vehicle continues to travel at approximately:', options: ['Its initial (unchanged) speed, covering additional distance before deceleration begins', 'Zero speed, since reaction time implies immediate stopping', 'An increasing speed, always accelerating during this period', 'A completely unpredictable, random speed'], correctIndex: 0, explanation: 'During the reaction time, before braking action physically begins, the vehicle continues moving at approximately its initial speed, covering extra distance.', difficulty: 'medium' },
  { id: 'msl-86', type: 'assertion', question: 'Assertion (A): The total stopping distance of a vehicle includes both the distance covered during the driver\'s reaction time and the distance covered during braking (deceleration).\nReason (R): Since the vehicle continues moving at its initial speed during the reaction time before brakes are physically applied, this additional distance must be added to the braking distance to obtain the total stopping distance.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The combination of reaction-time distance and braking distance correctly explains why total stopping distance accounts for both components.', difficulty: 'medium' },
  { id: 'msl-87', type: 'count', question: 'Consider the following statements about stopping distance and reaction time:\n1. Reaction time is the delay between perceiving a hazard and physically initiating a response.\n2. During reaction time, a moving vehicle instantly stops, covering zero additional distance.\n3. Total stopping distance includes both reaction-time distance and braking distance.\n4. For a given speed, greater deceleration during braking leads to a shorter stopping distance.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — during reaction time, the vehicle continues moving at approximately its initial speed, covering non-zero additional distance.', difficulty: 'medium' },

  // ============ MIXED / REVISION ============
  { id: 'msl-88', type: 'mcq', question: 'Which of the following pairs is INCORRECTLY matched (quantity and its scalar/vector nature)?', options: ['Distance — Scalar', 'Displacement — Vector', 'Speed — Vector', 'Velocity — Vector'], correctIndex: 2, explanation: 'Speed is a scalar quantity, not a vector; it has magnitude only, without any associated direction.', difficulty: 'medium' },
  { id: 'msl-89', type: 'mcq', question: 'Which of the following graph interpretations is INCORRECT?', options: ['Slope of position-time graph = velocity', 'Slope of velocity-time graph = acceleration', 'Area under velocity-time graph = displacement', 'Area under position-time graph = acceleration'], correctIndex: 3, explanation: 'The area under a position-time graph does not have a standard direct physical interpretation like acceleration; the correct graph-based interpretations relate slope to velocity/acceleration and area (under v-t graph) to displacement.', difficulty: 'hard' },
  { id: 'msl-90', type: 'assertion', question: 'Assertion (A): The concepts of motion in a straight line (kinematics) form a foundational basis for understanding more complex motion in two and three dimensions.\nReason (R): The fundamental quantities and relationships developed for one-dimensional motion — displacement, velocity, acceleration, and their graphical and equational relationships — extend, with vector generalisation, to describe motion in higher dimensions.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The extendability of one-dimensional kinematic concepts to higher-dimensional motion, through vector generalisation, correctly explains why this chapter is foundational to further study of motion.', difficulty: 'medium' },
  { id: 'msl-91', type: 'count', question: 'Consider the following statements summarising the chapter:\n1. Motion is always described relative to a chosen frame of reference.\n2. Distance and displacement are always numerically equal, in every type of motion.\n3. The standard equations of motion apply specifically to uniformly accelerated motion.\n4. Graphical methods (position-time and velocity-time graphs) provide useful tools for analysing motion.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — distance and displacement are equal only for straight-line motion without any reversal in direction, not in every type of motion.', difficulty: 'medium' },
  { id: 'msl-92', type: 'statement', question: 'Statement I: In one-dimensional motion, velocity and acceleration can be represented using positive and negative signs, based on a chosen reference direction.\nStatement II: This sign convention allows the same set of scalar-like equations (with appropriate signs) to describe vector quantities in straight-line motion.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct, and Statement II correctly builds on Statement I', 'Both statements are correct but unrelated', 'Statement I is correct, Statement II is incorrect', 'Statement I is incorrect, Statement II is correct'], correctIndex: 0, explanation: 'The sign convention (Statement I) is precisely what allows vector quantities to be handled with simple algebraic equations in one-dimensional motion, as explained in Statement II.', difficulty: 'medium' },
];

